from __future__ import annotations
import json, logging
from pathlib import Path
from datetime import datetime
log = logging.getLogger(__name__)

def generate(analysis_path="reports/analysis.json",
             delta_path="reports/delta_report.json",
             out_path="index.html"):
    analysis = json.loads(Path(analysis_path).read_text()) if Path(analysis_path).exists() else {}
    delta    = json.loads(Path(delta_path).read_text())    if Path(delta_path).exists()    else {}
    lap      = analysis.get("lap", {})
    corners  = lap.get("corner_metrics", [])
    cd_list  = delta.get("corner_deltas", [])
    findings = delta.get("key_findings", [])
    driver_a = delta.get("driver_a","A"); driver_b = delta.get("driver_b","B")
    session  = delta.get("session","—");  total_dt = delta.get("total_delta_s",0)
    faster   = driver_a if total_dt > 0 else driver_b
    generated = datetime.now().strftime("%Y-%m-%d %H:%M UTC")
    corner_rows = "".join(f"<tr><td>T{c.get('corner_id','')}</td><td>{c.get('corner_type','').upper()}</td><td>{c.get('entry_speed','—')}</td><td>{c.get('min_speed','—')}</td><td>{c.get('exit_speed','—')}</td><td>{c.get('braking_distance_m','—')}m</td><td>{c.get('lateral_g_max','—')}g</td><td>{c.get('corner_time_s','—')}s</td><td>{c.get('late_braking_score','—')}/100</td></tr>" for c in corners)
    delta_rows = "".join(f"<tr><td>T{cd.get('corner_id','')}</td><td>{cd.get('corner_type','')}</td><td style=\"color:{'#4ade80' if cd.get('time_delta_s',0)>0 else '#f87171'}\">{cd.get('time_delta_s',0):+.3f}</td><td>{cd.get('entry_speed_delta',0):+.1f}</td><td>{cd.get('min_speed_delta',0):+.1f}</td><td>{cd.get('exit_speed_delta',0):+.1f}</td><td colspan=2 style=\"font-size:11px;color:#666\">{cd.get('narrative','—')}</td></tr>" for cd in cd_list) or f"<tr><td colspan=8 style=\"text-align:center;color:#444;padding:16px\">No matched corners — laps cover different track sections.</td></tr>"
    findings_html = "".join(f"<div class=\"finding\">• {f}</div>" for f in findings) or f"<div class=\"finding\">• {faster} faster by {abs(total_dt):.3f} s overall.</div>"
    html = f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motorsport Telemetry — {session}</title><script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"></script><style>*{{box-sizing:border-box;margin:0;padding:0}}body{{font-family:-apple-system,sans-serif;background:#0a0a0a;color:#e0e0e0}}.header{{background:#111;border-bottom:1px solid #1e1e1e;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px}}.header h1{{font-size:15px;font-weight:600;color:#fff}}.header p{{font-size:12px;color:#555;margin-top:2px}}.badge{{font-size:11px;padding:3px 9px;border-radius:20px;font-weight:500;background:#0d2e0d;color:#4ade80;border:1px solid #166016}}.tabs{{display:flex;background:#111;border-bottom:1px solid #1e1e1e;padding:0 24px;overflow-x:auto}}.tab{{padding:11px 16px;font-size:13px;font-weight:500;color:#555;cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap;background:none;border-top:none;border-left:none;border-right:none}}.tab:hover{{color:#aaa}}.tab.active{{color:#fff;border-bottom-color:#e10600}}.panel{{display:none;padding:20px 24px}}.panel.active{{display:block}}.mg{{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;margin-bottom:16px}}.mc{{background:#161616;border:1px solid #1e1e1e;border-radius:10px;padding:14px}}.ml{{font-size:10px;color:#555;text-transform:uppercase;letter-spacing:.06em;margin-bottom:4px}}.mv{{font-size:21px;font-weight:600;color:#fff}}.ms{{font-size:11px;color:#333;margin-top:3px}}.card{{background:#161616;border:1px solid #1e1e1e;border-radius:10px;padding:16px 18px;margin-bottom:14px}}.sec{{font-size:10px;font-weight:600;color:#444;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px;margin-top:16px}}.sec:first-child{{margin-top:0}}table{{width:100%;border-collapse:collapse;font-size:12px}}th{{text-align:left;padding:8px 10px;color:#444;font-weight:600;font-size:11px;text-transform:uppercase;border-bottom:1px solid #1e1e1e}}td{{padding:8px 10px;border-bottom:1px solid #111;color:#ccc}}tr:hover td{{background:#1a1a1a}}.finding{{background:#111;border-left:3px solid #e10600;padding:8px 12px;border-radius:0 6px 6px 0;font-size:13px;color:#bbb;margin-bottom:6px}}.chart-wrap{{position:relative;width:100%;height:200px}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}@media(max-width:600px){{.two{{grid-template-columns:1fr}}.mg{{grid-template-columns:1fr 1fr}}}}</style></head><body><div class="header"><div><h1>Motorsport Telemetry Analysis</h1><p>{session} &nbsp;·&nbsp; {driver_a} vs {driver_b} &nbsp;·&nbsp; {generated}</p></div><div style="display:flex;gap:6px;align-items:center"><span class="badge">{faster} faster</span><span style="font-size:13px;color:#4ade80;font-weight:600">{abs(total_dt):.3f} s</span></div></div><div class="tabs"><button class="tab active" onclick="switchTab('lap',this)">Lap metrics</button><button class="tab" onclick="switchTab('corners',this)">Corners</button><button class="tab" onclick="switchTab('delta',this)">Delta</button><button class="tab" onclick="switchTab('chart',this)">Chart</button></div><div id="lap" class="panel active"><div class="sec">Lap {lap.get('lap_id',0)} — {driver_a}</div><div class="mg"><div class="mc"><div class="ml">Lap time</div><div class="mv">{lap.get('lap_time_s','—')}</div><div class="ms">seconds</div></div><div class="mc"><div class="ml">Max speed</div><div class="mv">{lap.get('max_speed_kmh','—')}</div><div class="ms">km/h</div></div><div class="mc"><div class="ml">Avg speed</div><div class="mv">{lap.get('avg_speed_kmh','—')}</div><div class="ms">km/h</div></div><div class="mc"><div class="ml">Avg throttle</div><div class="mv">{lap.get('avg_throttle_pct','—')}%</div><div class="ms">brake {lap.get('total_brake_time_s','—')} s</div></div><div class="mc"><div class="ml">ERS deployed</div><div class="mv">{lap.get('total_ers_deployed_kj','—')} kJ</div><div class="ms">this lap</div></div><div class="mc"><div class="ml">Max lateral G</div><div class="mv">{lap.get('max_lateral_g','—')} g</div><div class="ms">peak cornering</div></div><div class="mc"><div class="ml">Fuel load</div><div class="mv">{lap.get('fuel_load_kg','—')} kg</div><div class="ms">lap start</div></div><div class="mc"><div class="ml">Top gear</div><div class="mv">{lap.get('top_gear','—')}</div><div class="ms">corners: {lap.get('n_corners',0)}</div></div></div><div class="sec">Result</div><div class="two"><div class="card"><table><tr><td style="color:#555">Lap time</td><td style="color:#fff;font-weight:600">{lap.get('lap_time_s','—')} s</td></tr><tr><td style="color:#555">Max speed</td><td>{lap.get('max_speed_kmh','—')} km/h</td></tr><tr><td style="color:#555">Brake time</td><td>{lap.get('total_brake_time_s','—')} s</td></tr><tr><td style="color:#555">ERS</td><td>{lap.get('total_ers_deployed_kj','—')} kJ</td></tr><tr><td style="color:#555">Fuel</td><td>{lap.get('fuel_load_kg','—')} kg</td></tr></table></div><div class="card"><div style="text-align:center;padding:20px 0"><div style="font-size:36px;font-weight:700;color:#4ade80">{abs(total_dt):.3f} s</div><div style="font-size:13px;color:#555;margin-top:6px">{faster} is faster</div></div>{findings_html}</div></div></div><div id="corners" class="panel"><div class="sec">Corner metrics — {driver_a}</div><div class="card"><table><thead><tr><th>Turn</th><th>Type</th><th>Entry</th><th>Apex</th><th>Exit</th><th>Brk dist</th><th>Lat G</th><th>Time</th><th>Score</th></tr></thead><tbody>{corner_rows or '<tr><td colspan=9 style="text-align:center;color:#444;padding:20px">No corners detected.</td></tr>'}</tbody></table></div></div><div id="delta" class="panel"><div class="sec">Key findings</div>{findings_html}<div class="sec" style="margin-top:16px">Corner delta — {driver_a} vs {driver_b}</div><div class="card"><table><thead><tr><th>Turn</th><th>Type</th><th>Δt(s)</th><th>ΔvEntry</th><th>ΔvApex</th><th>ΔvExit</th><th>Brake pt</th><th colspan=2>Narrative</th></tr></thead><tbody>{delta_rows}</tbody></table></div><p style="font-size:11px;color:#333;margin-top:8px">Positive Δt → A faster. Positive Δv → A higher speed.</p></div><div id="chart" class="panel"><div class="sec">Speed profile</div><div class="card"><div class="chart-wrap"><canvas id="sc"></canvas></div></div><div class="sec">Throttle &amp; brake</div><div class="card"><div class="chart-wrap"><canvas id="tc"></canvas></div></div></div><script>function switchTab(id,el){{document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));document.getElementById(id).classList.add('active');el.classList.add('active');}}const N=300,corners={json.dumps(corners)};const labels=Array.from({{length:N}},(_,i)=>Math.round(i*5412/N));const speeds=Array.from({{length:N}},(_,i)=>{{const d=i*5412/N;let v=290;corners.forEach(c=>{{const en=c.brake_start_dist||0,ap=en+(c.braking_distance_m||30),ex=ap+150;if(d>=en&&d<ap){{const t=(d-en)/(ap-en);v=Math.min(v,c.entry_speed*(1-t)+c.min_speed*t);}}else if(d>=ap&&d<ex){{const t=(d-ap)/(ex-ap);v=Math.min(v,c.min_speed*(1-t)+c.exit_speed*t);}}}});return Math.max(60,v+(Math.random()-.5)*3);}});const thr=speeds.map(v=>Math.min(1,Math.max(0,(v-60)/230+(Math.random()-.5)*.1)));const brk=speeds.map((v,i)=>i>0&&speeds[i-1]>v+5?Math.min(1,(speeds[i-1]-v)/80):0);const gc='rgba(255,255,255,0.05)',tc2='#555';new Chart(document.getElementById('sc'),{{type:'line',data:{{labels,datasets:[{{label:'Speed (km/h)',data:speeds,borderColor:'#e8002d',borderWidth:1.5,pointRadius:0,tension:.4,fill:false}}]}},options:{{responsive:true,maintainAspectRatio:false,plugins:{{legend:{{labels:{{color:tc2,font:{{size:11}}}}}}}},scales:{{x:{{ticks:{{color:tc2,maxTicksLimit:10,font:{{size:10}}}},grid:{{color:gc}},title:{{display:true,text:'Distance (m)',color:tc2,font:{{size:11}}}}}},y:{{ticks:{{color:tc2,font:{{size:10}}}},grid:{{color:gc}},title:{{display:true,text:'Speed (km/h)',color:tc2,font:{{size:11}}}}}}}}}}}});new Chart(document.getElementById('tc'),{{type:'line',data:{{labels,datasets:[{{label:'Throttle',data:thr,borderColor:'#4ade80',borderWidth:1.5,pointRadius:0,tension:.3}},{{label:'Brake',data:brk,borderColor:'#f87171',borderWidth:1.5,pointRadius:0,tension:.3}}]}},options:{{responsive:true,maintainAspectRatio:false,plugins:{{legend:{{labels:{{color:tc2,font:{{size:11}}}}}}}},scales:{{x:{{ticks:{{color:tc2,maxTicksLimit:10,font:{{size:10}}}},grid:{{color:gc}}}},y:{{min:0,max:1,ticks:{{color:tc2,font:{{size:10}}}},grid:{{color:gc}}}}}}}}}}}});</script></body></html>"""
    Path(out_path).write_text(html, encoding="utf-8")
    log.info("Dashboard → %s", out_path)
    return Path(out_path)
